// A plain-English, human-readable rendering of a policy document — per explicit user
// request, purely descriptive: NEVER consulted by evaluate.ts or anything that
// determines an actual decision. The same "LLM/prose for reading, deterministic code
// for anything that has to be right" boundary this app already draws elsewhere,
// applied to documentation instead of a conversation.
//
// Deliberately NOT generated by an LLM call. Every setting, fact and rule in the schema
// already carries a mandatory, human-authored `description` (rules also carry
// `outcome.explanation`) specifically because they're meant to read as plain English.
// This just walks the document and assembles those existing strings into organized,
// ordered prose — structurally impossible to drift from what the evaluator actually does,
// since it reads the identical document.
//
// The shape follows how a request is decided:
// RESTRICTIONS first (any one sends the case to a person), grouped by who they apply to;
// then the explicit DECISIONS (the only way anything is decided automatically); then the
// fallback (a person). Returns structured data so the frontend can render real headings
// and lists instead of a wall of preformatted text.

import type { PolicyDocument, Reason } from "./schema";

const DECISION_LABEL: Record<string, string> = {
  autonomous_approve: "Approved automatically",
  autonomous_deny: "Declined automatically",
  escalate: "Sent to a specialist for review",
  always_escalate: "Always sent to a specialist for review",
};

function decisionLabel(decision: string): string {
  return DECISION_LABEL[decision] ?? decision;
}

// Plain names for the reasons a customer may want money back. A rule with no `appliesTo` applies to all of them.
const REASON_LABEL: Record<Reason, string> = {
  damaged_or_defective: "Damaged or defective",
  not_wanted: "Not wanted (plain returns)",
  not_delivered: "Not delivered (delivery disputes)",
};

export const ALL_REASONS_LABEL = "Every refund or return";

export function scopeLabel(appliesTo?: readonly Reason[]): string {
  if (!appliesTo || appliesTo.length === 0) return ALL_REASONS_LABEL;
  return appliesTo.map((reason) => REASON_LABEL[reason] ?? reason).join(" · ");
}

export interface SynopsisRuleEntry {
  number?: string; // the rule's policy number (P1, P2, …) — a lookup handle
  kind: "restriction" | "decision" | "fallback";
  appliesTo: string; // who it applies to, e.g. "Every refund or return"
  when: string; // the rule's own `description` — when this fires
  then: string; // the outcome's own `explanation` — what happens
  decision: string; // the raw decision value, for the frontend to badge/color
  decisionLabel: string;
}

export interface SynopsisGroup {
  title: string; // who the rules in this group apply to
  rules: SynopsisRuleEntry[]; // in document order
}

export interface SynopsisSetting {
  name: string;
  value: number | boolean;
  description: string;
}

export interface PolicySynopsis {
  name: string;
  version: number;
  description?: string;
  settings: SynopsisSetting[];
  // Any one of these sends a request to a person. Grouped by who they apply to, "every refund or return" first.
  restrictions: SynopsisGroup[];
  // The only rules that decide something automatically — reached only when no restriction applied.
  decisions: SynopsisGroup[];
  // Reached when no restriction applied and no decision authorized an outcome: always a person.
  fallback: SynopsisRuleEntry;
}

function groupBy(entries: Array<{ scope: string; entry: SynopsisRuleEntry }>): SynopsisGroup[] {
  const groups = new Map<string, SynopsisRuleEntry[]>();
  for (const { scope, entry } of entries) groups.set(scope, [...(groups.get(scope) ?? []), entry]);
  // "Every refund or return" leads; the rest keep the order in which they first appear.
  const titles = [...groups.keys()].sort((a, b) => (a === ALL_REASONS_LABEL ? -1 : b === ALL_REASONS_LABEL ? 1 : 0));
  return titles.map((title) => ({ title, rules: groups.get(title)! }));
}

export function buildPolicySynopsis(document: PolicyDocument): PolicySynopsis {
  const entryFor = (rule: PolicyDocument["rules"][number]): { scope: string; entry: SynopsisRuleEntry } => {
    const scope = scopeLabel(rule.appliesTo);
    return {
      scope,
      entry: {
        number: rule.number,
        kind: rule.kind,
        appliesTo: scope,
        when: rule.description,
        then: rule.outcome.explanation,
        decision: rule.outcome.decision,
        decisionLabel: decisionLabel(rule.outcome.decision),
      },
    };
  };

  return {
    name: document.metadata.name,
    version: document.metadata.version,
    description: document.metadata.description,
    settings: Object.entries(document.settings).map(([name, setting]) => ({
      name,
      value: setting.value,
      description: setting.description,
    })),
    restrictions: groupBy(document.rules.filter((rule) => rule.kind === "restriction").map(entryFor)),
    decisions: groupBy(document.rules.filter((rule) => rule.kind === "decision").map(entryFor)),
    fallback: {
      number: document.fallback.number,
      kind: "fallback",
      appliesTo: ALL_REASONS_LABEL,
      when: "Otherwise",
      then: document.fallback.explanation,
      decision: document.fallback.decision,
      decisionLabel: decisionLabel(document.fallback.decision),
    },
  };
}

// The plain-English version of ONE rule (or the fallback, with when = "Otherwise") — the same wording the
// Policies page shows for it. Snapshotted onto a case when that rule decides it (live-policy.ts), so the
// Escalation Desk's hover text stays what the rule said at the time, even after the policy later changes.
// Three short lines (the Desk renders it with line breaks kept): who it applies to, when, and what it does.
export function policyRuleText(scope: string, when: string, outcome: { decision: string; explanation: string }): string {
  const applies = when === "Otherwise" ? "No restriction applied and no rule authorized an automatic outcome." : when;
  return `${scope}\nWhen: ${applies}\nThen: ${decisionLabel(outcome.decision)} — ${outcome.explanation}`;
}
